 var ph=document.getElementById('f-ph').value.replace(/\D/g,'').slice(-11),er='';if(!h)er='Your cart is empty';else if(!/^01\d{9}$/.test(ph))er='সঠিক মোবাইল নম্বর লিখুন (01XXXXXXXXX)';else if(!document.getElementById('f-nm').value.trim()||!document.getElementById('f-ad').value.trim())er='মোবাইল নম্বর, নাম ও ঠিকানা লিখুন।';
 var pmv=document.querySelector('input[name=pay]:checked');if(!er&&pmv&&pmv.value!=='cod'&&pmv.value!=='shurjopay'){if(document.getElementById('pay-tx').value.trim().length<4)er='Transaction ID / Reference দিন';else if(pmv.value==='bank'&&!document.querySelector('input[name=pay_account]:checked'))er='কোন ব্যাংক অ্যাকাউন্টে টাকা পাঠিয়েছেন সেটি বেছে নিন';if(er){var tf=document.getElementById('pay-tx');if(er.indexOf('Transaction')===0&&tf){tf.scrollIntoView({behavior:'smooth',block:'center'});tf.focus();tf.style.borderColor='#DC2626'}else{var bk=document.querySelector('#pd-bank');if(bk)bk.scrollIntoView({behavior:'smooth',block:'start'})}}}if(er){e.preventDefault();alertBox(er);return}var sb=document.getElementById('sbm');if(sb.dataset.busy==='1'){e.preventDefault();return}sb.dataset.busy='1';sb.dataset.t=sb.textContent;sb.textContent='Processing...';sb.disabled=true;setTimeout(function(){sb.dataset.busy='';sb.disabled=false;sb.textContent=sb.dataset.t||'ORDER SUBMIT'},25000);var cc=DF.cart(),its=[],tv=0;for(var k in cc){its.push({item_id:String(cc[k].x||k),price:cc[k].p,quantity:cc[k].q});tv+=cc[k].p*cc[k].q}try{if(window.fbq&&@json(!empty($s['pixel_id']))){var _p=(document.getElementById('f-ph').value||'').replace(/\D/g,'').slice(-10),_n=(document.getElementById('f-nm').value||'').trim().toLowerCase().split(/\s+/),_m=(document.getElementById('f-em').value||'').trim().toLowerCase(),_a={country:'bd'};if(_p.length==10)_a.ph='880'+_p;if(_m)_a.em=_m;if(_n[0])_a.fn=_n[0];if(_n.length>1)_a.ln=_n.slice(1).join(' ');fbq('init',@json($s['pixel_id'] ?? ''),_a)}}catch(x){}DF.pay(true);};
