function run(){var p=ph();if(!/^01\d{9}$/.test(p)){box.style.display='none';last='';return}if(p===last)return;last=p;
 var sv=null;try{sv=JSON.parse(localStorage.getItem('df_cust')||'null')}catch(e){}
 if(sv&&sv.p===p){fill({name:sv.n,email:sv.e,address:sv.a,district:sv.d});return}
 post('/checkout/lookup',{phone:p}).then(function(j){if(!j.found||ph()!==p){box.style.display='none';return}if(j.d){fill(j.d);return}box.style.display='block';
  if(!j.otp){box.innerHTML='👋 স্বাগতম, '+j.hint+' — আবার অর্ডার করছেন! তথ্য নিচে লিখুন।';return}
  box.innerHTML='👋 স্বাগতম, <b>'+j.hint+'</b>! আগের তথ্য স্বয়ংক্রিয়ভাবে বসাতে এই নম্বরে একটি SMS কোড পাঠানো হবে। <button type="button" id="afs" style="margin-left:6px;padding:4px 10px;border-radius:8px;border:0;background:#16A34A;color:#fff;font-weight:700">কোড পাঠান</button><span id="afc"></span>';
  function ask(){var c=document.getElementById('afc');c.innerHTML='<br>কোড পাঠানো হচ্ছে…';post('/checkout/otp',{phone:p}).then(function(o){c.innerHTML='<br>'+(o.sent?'✅ SMS পাঠানো হয়েছে।':(o.wait?'আগে পাঠানো কোডটি ব্যবহার করুন, নতুন কোডের জন্য ১ মিনিট অপেক্ষা করুন।':'কোড পাঠানো যায়নি।'))+'<br><input id="afi" inputmode="numeric" maxlength="6" placeholder="৬ সংখ্যার কোড" style="width:140px;padding:7px 9px;border:1px solid #86EFAC;border-radius:8px;font-size:15px"> <button type="button" id="afv" style="padding:6px 12px;border-radius:8px;border:0;background:#0B1220;color:#fff;font-weight:700">যাচাই</button> <button type="button" id="afr" style="padding:6px 10px;border-radius:8px;border:1px solid #16A34A;background:#fff;color:#16A34A;font-weight:700">আবার পাঠান</button><span id="afe" style="color:#B91C1C"></span>';
   document.getElementById('afr').onclick=ask;document.getElementById('afi').focus();
   document.getElementById('afv').onclick=function(){post('/checkout/verify',{phone:p,code:document.getElementById('afi').value}).then(function(v){if(v.ok)fill(v.d);else document.getElementById('afe').textContent=' কোড সঠিক নয়'}).catch(function(){document.getElementById('afe').textContent=' সমস্যা হয়েছে, আবার চেষ্টা করুন'})}}).catch(function(){c.innerHTML='<br>সমস্যা হয়েছে, আবার চেষ্টা করুন।'})}
  document.getElementById('afs').onclick=function(){this.style.display='none';ask()}}).catch(function(){})}
