function send(beacon){var ph=document.getElementById('f-ph').value.replace(/\D/g,'').slice(-11);if(!/^01\d{9}$/.test(ph)||!ids())return;if(beacon&&navigator.sendBeacon){navigator.sendBeacon('/checkout/track',new Blob([body()],{type:'text/plain'}));return}fetch('/checkout/track',{method:'POST',headers:{'Content-Type':'application/json'},body:body(),keepalive:true}).then(function(r){return r.json()}).then(function(j){if(j&&j.done){tok='';try{localStorage.removeItem('dfinc')}catch(e){}}}).catch(function(){})}
